182	static bool mi_option_has_size_in_kib(mi_option_t option) {
183	  return (option == mi_option_reserve_os_memory || option == mi_option_arena_reserve ||
184	          option == mi_option_minimal_purge_size || option == mi_option_arena_max_object_size);
185	}
