187	void _mi_options_init(void) {
188	  // called on process load
189	  for(int i = 0; i < _mi_option_last; i++ ) {
190	    mi_option_t option = (mi_option_t)i;
191	    long l = mi_option_get(option); MI_UNUSED(l); // initialize
192	  }
193	  mi_max_error_count = mi_option_get(mi_option_max_errors);
194	  mi_max_warning_count = mi_option_get(mi_option_max_warnings);
195	  #if MI_GUARDED
196	  if (mi_option_get(mi_option_guarded_sample_rate) > 0) {
197	    if (mi_option_is_enabled(mi_option_allow_large_os_pages)) {
198	      mi_option_disable(mi_option_allow_large_os_pages);
199	      _mi_warning_message("option 'allow_large_os_pages' is disabled to allow for guarded objects\n");
200	    }
201	  }
202	  #endif
203	}
