214	mi_decl_export void mi_options_print_out(mi_output_fun* out, void* arg) mi_attr_noexcept
215	{
216	  // show version
217	  const int vermajor = MI_MALLOC_VERSION/10000;
218	  const int verminor = (MI_MALLOC_VERSION%10000)/100;
219	  const int verpatch = (MI_MALLOC_VERSION%100);
220	  _mi_fprintf(out, arg, "v%i.%i.%i%s%s\n", vermajor, verminor, verpatch,
221	      #if defined(MI_CMAKE_BUILD_TYPE)
222	      ", " mi_stringify(MI_CMAKE_BUILD_TYPE)
223	      #else
224	      ""
225	      #endif
226	      ,
227	      #if defined(MI_GIT_DESCRIBE)
228	      ", git " mi_stringify(MI_GIT_DESCRIBE)
229	      #else
230	      ""
231	      #endif
232	      );
233	
234	  // show options
235	  for (int i = 0; i < _mi_option_last; i++) {
236	    mi_option_t option = (mi_option_t)i;
237	    long l = mi_option_get(option); MI_UNUSED(l); // possibly initialize
238	    mi_option_desc_t* desc = &mi_options[option];
239	    _mi_fprintf(out, arg, "option '%s': %ld %s\n", desc->name, desc->value, (mi_option_has_size_in_kib(option) ? "KiB" : ""));
240	  }
241	
242	  // show build configuration
243	  _mi_fprintf(out, arg, "debug level : %d\n", MI_DEBUG );
244	  _mi_fprintf(out, arg, "secure level: %d\n", MI_SECURE );
245	  _mi_fprintf(out, arg, "mem tracking: %s\n", MI_TRACK_TOOL);
246	  #if MI_GUARDED
247	  _mi_fprintf(out, arg, "guarded build: %s\n", mi_option_get(mi_option_guarded_sample_rate) != 0 ? "enabled" : "disabled");
248	  #endif
249	  #if MI_TSAN
250	  _mi_fprintf(out, arg, "thread santizer enabled\n");
251	  #endif
252	  #if MI_PAGE_META_IS_ALIGNED
253	  _mi_fprintf(out, arg, "free: aligned, page size: %zu\n", sizeof(mi_page_t));
254	  #elif MI_FREE_IS_CHECKED
255	  _mi_fprintf(out, arg, "free: checked, page size: %zu\n", sizeof(mi_page_t));
256	  #endif
257	  #if MI_ENCODE_FREELIST
258	  _mi_fprintf(out, arg, "free lists: encoded with %d key(s)\n", MI_PAGE_KEY_COUNT);
259	  #endif
260	}
