266	long _mi_option_get_fast(mi_option_t option) {
267	  mi_assert(option >= 0 && option < _mi_option_last);
268	  mi_option_desc_t* desc = &mi_options[option];
269	  mi_assert(desc->option == option);  // index should match the option
270	  //mi_assert(desc->init != MI_OPTION_UNINIT);
271	  return desc->value;
272	}
