291	mi_decl_nodiscard size_t mi_option_get_size(mi_option_t option) {
292	  const long x = mi_option_get(option);
293	  size_t size = (x < 0 ? 0 : (size_t)x);
294	  if (mi_option_has_size_in_kib(option)) {
295	    if (mi_mul_overflow(size, MI_KiB, &size)) {
296	      size = MI_MAX_ALLOC_SIZE;
297	    }
298	  }
299	  return size;
300	}
