400	// Once this module is loaded, switch to this routine
401	// which outputs to stderr and the delayed output buffer.
402	static void mi_cdecl mi_out_buf_stderr(const char* msg, void* arg) {
403	  mi_out_stderr(msg,arg);
404	  mi_out_buf(msg,arg);
405	}
